-- Security self-audit fixes: branding bucket, truncate guard, deny-all notes, failed sign-in log rights. Rolled back.
select pg_temp.ok((select allowed_mime_types from storage.buckets where id = 'branding') @> array['image/png', 'image/jpeg']::text[]
  and cardinality((select allowed_mime_types from storage.buckets where id = 'branding')) = 2, 'branding bucket: PNG and JPG only, no SVG');
select pg_temp.ok(not (select public from storage.buckets where id = 'student-photos') and not (select public from storage.buckets where id = 'student-documents')
  and not (select public from storage.buckets where id = 'payment-qr') and not (select public from storage.buckets where id = 'diary-files') and not (select public from storage.buckets where id = 'notice-files'), 'every bucket except branding is private');
select pg_temp.ok(exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'app' and p.proname = 'block_audit_truncate' and exists (select 1 from unnest(p.proconfig) c where c like 'search_path=%')), 'audit truncate guard: search_path is fixed');
select pg_temp.ok((select count(*) from pg_description d join pg_class c on c.oid = d.objoid where c.relname in ('number_sequences', 'translation_cache', 'translation_usage') and d.description like '%NO policy on purpose%') = 3, 'the three deny-all tables say so in their comment');
select pg_temp.ok(not has_function_privilege('anon', 'public.log_failed_login(text,text,text)', 'execute') and not has_function_privilege('authenticated', 'public.log_failed_login(text,text,text)', 'execute')
  and has_function_privilege('service_role', 'public.log_failed_login(text,text,text)', 'execute'), 'failed sign-in log: only the server (service role) may call it');
select pg_temp.ok(not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname = 'log_failed_login' and pg_get_function_identity_arguments(p.oid) = 'p_email text'), 'the old one-argument version is gone');
select pg_temp.ok(not exists (select 1 from public.school_settings where lower(logo_path) like '%.svg' or lower(principal_signature_path) like '%.svg'), 'no setting points at an SVG image');
